const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countryName = 'Zimbabwe';
  const startDate2023 = '2023-02-01';
  const endDate2023 = '2023-02-28'; // 2023 is not a leap year
  const startDate2024 = '2024-02-01';
  const endDate2024 = '2024-02-29'; // 2024 is a leap year

  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
  const geometry = countries.filter(ee.Filter.eq('ADM0_NAME', countryName)).geometry();

  // Check if geometry is found
  if (geometry.area().getInfo() === 0) {
    console.log("Error: Could not find geometry for " + countryName);
    console.log("D");
    return;
  }

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  const collection2023 = chirps.filterDate(startDate2023, endDate2023).filterBounds(geometry);
  const collection2024 = chirps.filterDate(startDate2024, endDate2024).filterBounds(geometry);

  // 2.1. Data Check (C1)
  const size2023 = await collection2023.size().getInfo();
  const size2024 = await collection2024.size().getInfo();

  if (size2023 === 0 || size2024 === 0) {
    console.log(`2023 Images: ${size2023}`);
    console.log(`2024 Images: ${size2024}`);
    console.log("C1");
    return;
  }

  // 3. Processing: Calculate total rainfall for each period
  const totalRainfall2023 = collection2023.sum().select('precipitation');
  const totalRainfall2024 = collection2024.sum().select('precipitation');

  // Define a scale for reduceRegion (CHIRPS resolution is ~5km, so 5000m is appropriate)
  const scale = 5000; 

  // 3.1. Pixel Count Check (C2) for 2023
  const pixelCount2023 = await totalRainfall2023.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  if (pixelCount2023 === 0) {
    console.log("2023 Images: " + size2023 + " (Val: " + pixelCount2023 + ")");
    console.log("No valid pixels for 2023 after processing.");
    console.log("C2");
    return;
  }

  // 3.2. Pixel Count Check (C2) for 2024
  const pixelCount2024 = await totalRainfall2024.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  if (pixelCount2024 === 0) {
    console.log("2024 Images: " + size2024 + " (Val: " + pixelCount2024 + ")");
    console.log("No valid pixels for 2024 after processing.");
    console.log("C2");
    return;
  }

  // 4. Calculation: Average total rainfall over the geometry
  const meanRainfall2023 = await totalRainfall2023.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const meanRainfall2024 = await totalRainfall2024.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 5. Validation & Final Answer (C3, A/B)
  if (meanRainfall2023 === null || isNaN(meanRainfall2023) ||
      meanRainfall2024 === null || isNaN(meanRainfall2024)) {
    console.log("2023 Rainfall: " + meanRainfall2023);
    console.log("2024 Rainfall: " + meanRainfall2024);
    console.log("C3");
    return;
  }

  console.log(`Feb 2023 Avg Rainfall (mm): ${meanRainfall2023.toFixed(2)} (Pixels: ${pixelCount2023})`);
  console.log(`Feb 2024 Avg Rainfall (mm): ${meanRainfall2024.toFixed(2)} (Pixels: ${pixelCount2024})`);

  if (meanRainfall2024 < meanRainfall2023) {
    console.log("A"); // Yes, there was a decrease
  } else {
    console.log("B"); // No, there was not a decrease (it increased or stayed the same)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
